// Rebuilds vendor/pyodide/ from a Pyodide release. Only needed when upgrading
// Pyodide — the generated files are committed.
//
//   node tools/build-pyodide-vendor.js <dir with the npm `pyodide` package> <dir with the wheels>
//
//   npm pack pyodide@0.29.5 && tar xzf pyodide-0.29.5.tgz        → ./package
//   wheels: from pyodide-0.29.5.tar.bz2 on the Pyodide GitHub release
//           (sqlite3, numpy, pandas, python_dateutil, pytz, six)
//
// Why base64: the app must run by double-clicking index.html, and browsers
// refuse to fetch() local files from file://. So every binary Pyodide would
// download is embedded in a plain <script> as base64 (the wasm gzipped first),
// and python.js answers Pyodide's fetches from those strings.
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const [pkgDir, wheelDir] = process.argv.slice(2);
if (!pkgDir || !wheelDir) { console.error('usage: node tools/build-pyodide-vendor.js <pyodide package dir> <wheels dir>'); process.exit(1); }
const OUT = path.join(__dirname, '..', 'vendor', 'pyodide');
fs.mkdirSync(OUT, { recursive: true });

// Packages shipped beyond the core interpreter, grouped by the file they load from.
const BUNDLES = {
  'pyodide-sqlite3-b64.js': ['sqlite3'],
  'pyodide-pandas-b64.js': ['numpy', 'pandas', 'python-dateutil', 'pytz', 'six']
};

const lock = JSON.parse(fs.readFileSync(path.join(pkgDir, 'pyodide-lock.json'), 'utf8'));
const keep = Object.values(BUNDLES).flat();
const slim = { info: lock.info, packages: {} };
for (const name of keep) {
  if (!lock.packages[name]) throw new Error('not in lock file: ' + name);
  slim.packages[name] = lock.packages[name];
}

const HEAD = '// Generated by tools/build-pyodide-vendor.js — do not edit.\n(function (g) { const A = g.PYODIDE_ASSETS = g.PYODIDE_ASSETS || {};\n';
const TAIL = '})(typeof window !== "undefined" ? window : globalThis);\n';
const entry = (name, buf, gz) =>
  `A[${JSON.stringify(name)}] = { gz: ${gz}, b64: "${(gz ? zlib.gzipSync(buf, { level: 9 }) : buf).toString('base64')}" };\n`;

// Core: interpreter wasm (gzipped), stdlib zip (already compressed), slim lock file.
let core = HEAD;
core += entry('pyodide.asm.wasm', fs.readFileSync(path.join(pkgDir, 'pyodide.asm.wasm')), true);
core += entry('python_stdlib.zip', fs.readFileSync(path.join(pkgDir, 'python_stdlib.zip')), false);
core += `g.PYODIDE_LOCK = ${JSON.stringify(JSON.stringify(slim))};\n`;
core += `g.PYODIDE_VERSION = ${JSON.stringify(require(path.resolve(pkgDir, 'package.json')).version)};\n`;
fs.writeFileSync(path.join(OUT, 'pyodide-core-b64.js'), core + TAIL);

for (const [file, names] of Object.entries(BUNDLES)) {
  let src = HEAD;
  for (const n of names) {
    const fname = slim.packages[n].file_name;
    src += entry(fname, fs.readFileSync(path.join(wheelDir, fname)), false);
  }
  fs.writeFileSync(path.join(OUT, file), src + TAIL);
}

for (const f of ['pyodide.js', 'pyodide.asm.js']) fs.copyFileSync(path.join(pkgDir, f), path.join(OUT, f));
fs.writeFileSync(path.join(OUT, 'README.txt'),
`Pyodide ${require(path.resolve(pkgDir, 'package.json')).version} (CPython ${lock.info.python} compiled to WebAssembly) — https://pyodide.org
License: Mozilla Public License 2.0. Bundled packages keep their own licenses
(numpy, pandas: BSD-3-Clause; python-dateutil: Apache-2.0 / BSD; pytz: MIT; six: MIT).

pyodide.js, pyodide.asm.js   unmodified from the npm package
pyodide-core-b64.js          interpreter wasm (gzip) + standard library, base64
pyodide-sqlite3-b64.js       the sqlite3 module
pyodide-pandas-b64.js        numpy + pandas and their dependencies (loaded only by pandas lessons)

Regenerate with tools/build-pyodide-vendor.js.
`);
for (const f of fs.readdirSync(OUT)) console.log(f.padEnd(28), (fs.statSync(path.join(OUT, f)).size / 1048576).toFixed(2) + ' MB');
